pub fn validate_against(&self, request: &ReadFileChangeRequest) -> Result<(), AcpBoundaryError> {
    self.validate()?;
    let bytes = self.decoded_data()?;
    if self.session_id != request.session_id
        || self.request_id != request.request_id
        || self.side != request.side
        || self.offset != request.offset
        || (!self.eof && bytes.len() != request.length as usize)
    {
        return Err(AcpBoundaryError::InvalidSemanticValue);
    }
    Ok(())
}

