export function replaceHistoryTurnMetrics(
  view: AcpSessionView,
  turnMetrics: TurnLatencySummary,
): boolean {
  if (!view?.history || !turnMetrics?.turnId) return false;
  let updated = false;
  for (let index = view.history.length - 1; index >= 0; index -= 1) {
    const message = view.history[index];
    if (message?.role === 'assistant' && message.turnId === turnMetrics.turnId) {
      const next = { ...message, turnMetrics: mergeTurnLatencySummary(message.turnMetrics, turnMetrics) };
      view.history = [...view.history.slice(0, index), next, ...view.history.slice(index + 1)];
      updated = true;
    }
  }
  return updated;
}

